import { useRef } from 'react';
import { Animated, ListRenderItem } from 'react-native';

type Props = { data: string[]; renderItem: ListRenderItem<string> };

export function Feed({ data, renderItem }: Props) {
  const scrollY = useRef(new Animated.Value(0)).current;
  const shift = scrollY.interpolate({ inputRange: [0, 120], outputRange: [0, -120], extrapolate: 'clamp' });
  const onScroll = Animated.event(
    [{ nativeEvent: { contentOffset: { y: scrollY } } }],
    { useNativeDriver: false },
  );

  return (
    <>
      <Animated.FlatList data={data} renderItem={renderItem} onScroll={onScroll} scrollEventThrottle={16} />
      <Animated.View style={{ height: 120, transform: [{ translateY: shift }] }} />
    </>
  );
}

import { useState } from 'react';
import { TextInput } from 'react-native';
import debounce from 'lodash.debounce';
import { searchProducts } from '../api';

type Props = { onResults: (ids: string[]) => void };

export function SearchBox({ onResults }: Props) {
  const [text, setText] = useState('');
  const runSearch = debounce((q: string) => {
    searchProducts(q).then(onResults);
  }, 300);

  const onChangeText = (value: string) => {
    setText(value);
    runSearch(value);
  };

  return <TextInput value={text} onChangeText={onChangeText} />;
}

type Row = { id: string; raw: string };
type Parsed = { id: string; total: number };
declare function computeTotal(raw: string): number;

export async function importRows(
  rows: Row[],
  onProgress: (done: number) => void,
): Promise<Parsed[]> {
  const out: Parsed[] = [];
  for (let i = 0; i < rows.length; i += 200) {
    for (const row of rows.slice(i, i + 200)) {
      out.push({ id: row.id, total: computeTotal(row.raw) });
    }
    onProgress(out.length);
    await Promise.resolve();
  }
  return out;
}
